def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
      log10_id = Parameters[0] + Parameters[1] * gate_voltage_abs**2 + Parameters[2] * gate_voltage_abs * drain_voltage_abs + Parameters[3] * drain_voltage_abs**2 + Parameters[4] * gate_voltage_abs**3 + Parameters[5] * gate_voltage_abs**2 * drain_voltage_abs + Parameters[6] * gate_voltage_abs * drain_voltage_abs**2 + Parameters[7] * drain_voltage_abs**3 + Parameters[8] * gate_voltage_abs**3 * drain_voltage_abs + Parameters[9] * gate_voltage_abs * drain_voltage_abs * drain_voltage_abs + Parameters[10] * gate_voltage_abs**2 * drain_voltage_abs**2 + Parameters[11] * gate_voltage_abs * drain_voltage_abs**3
      return np.log10(np.abs(1 / np.exp(log10_id))) # This step is to ensure that the output is log10(|ID|/A)
